  int *q = counts + 2 * ctx;
  long long split = *range * (q[0] + 1) / (q[0] + q[1] + 2);
  int got = *frac >= split;
  if (got != want) return 0;
  if (got) { *frac -= split; *range -= split; }
  else *range = split;
  q[got]++;
  return 1;
}
