      int digit, found = 0;
      for (digit = 0; digit < 255; digit++) {
        long long tf = frac * 255 + digit, tr = range * 255;
        int trial[2000];
        memcpy(trial, counts, sizeof(trial));
        if (step(&tf, &tr, trial, bits.bit[i], bits.ctx[i])) { found = 1; break; }
      }
      if (!found) { fprintf(stderr, "no digit at bit %d\n", i); return 3; }
      if (oi == oc) { oc = oc ? oc * 2 : 1024; out = realloc(out, (size_t)oc); if (!out) return 10; }
      out[oi++] = (unsigned char)(digit + 1);
