  if (!f || fwrite(out, 1, (size_t)oi, f) != (size_t)oi) return 5;
  fclose(f);
  fprintf(stderr, "tokens=%d bits=%d compressed=%d\n", nt, bits.n, oi);
  return oi > 2500 ? 6 : 0;
}
