cat > /tmp/mkinterval.pl <<'EOF'
use strict; use warnings; use Math::BigInt;
open my $in, '<', 'bits.records' or die $!;
my $base=Math::BigInt->new(1); $base->bmul(255) for 1..2500;
my ($lo,$hi,$unit,$off,$rr)=(Math::BigInt->new(0),$base->copy,$base->copy,Math::BigInt->new(0),Math::BigInt->new(1));
my @c; my $n=0;
while (<$in>) {
 chomp; /^([01]) ([0-9]+)$/ or die "bad record";
 my($bit,$ctx)=($1,$2); my $ix=2*$ctx;
 if ($rr->bcmp(255)<0) { $rr->bmul(255); $off->bmul(255); $unit->bdiv(255); }
 my $den=($c[$ix]//0)+($c[$ix+1]//0)+2;
 my $sp=$rr->copy->bmul(($c[$ix]//0)+1)->bdiv($den);
 my $bd=$off->copy->badd($sp)->bmul($unit);
 if ($bit) { $lo=$bd if $lo->bcmp($bd)<0; $off->badd($sp); $rr->bsub($sp); }
 else { $hi=$bd if $hi->bcmp($bd)>0; $rr=$sp; }
 $c[$ix+$bit]=($c[$ix+$bit]//0)+1; $n++;
 die "empty interval at $n\n" if $lo->bcmp($hi)>=0;
}
die "wrong records $n\n" unless $n>1000;
my $x=$lo->copy; my @d;
for (1..2500) { unshift @d, $x->copy->bmod(255)->numify; $x->bdiv(255); }
die "overflow\n" unless $x->is_zero;
open my $out, '>:raw', 'data.comp' or die $!; print $out pack('C*', map {$_+1} @d); close $out;
print "records=$n interval_nonempty=1 bytes=".scalar(@d)."\n";
EOF
