#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#define N 800
typedef struct { uint32_t a[N]; } Big;
static void zero(Big*x){memset(x,0,sizeof *x);} static void one(Big*x){zero(x);x->a[0]=1;}
static void cp(Big*d,const Big*s){memcpy(d,s,sizeof *d);} static int cmp(const Big*a,const Big*b){for(int i=N-1;i>=0;i--)if(a->a[i]!=b->a[i])return a->a[i]>b->a[i]?1:-1;return 0;}
static void mulsmall(Big*x,uint32_t m){uint64_t c=0;for(int i=0;i<N;i++){uint64_t z=(uint64_t)x->a[i]*m+c;x->a[i]=(uint32_t)z;c=z>>32;}if(c){fprintf(stderr,"overflow\n");exit(2);}}
static uint32_t divsmall(Big*x,uint32_t d){uint64_t r=0;for(int i=N-1;i>=0;i--){uint64_t z=(r<<32)|x->a[i];x->a[i]=z/d;r=z%d;}return r;}
static void fromsmall(Big*x,uint32_t v){zero(x);x->a[0]=v;}
static void sub(Big*x,const Big*y){uint64_t borrow=0;for(int i=0;i<N;i++){uint64_t yi=(uint64_t)y->a[i]+borrow; uint64_t xi=x->a[i]; x->a[i]=(uint32_t)(xi-yi);borrow=xi<yi;}if(borrow){fprintf(stderr,"underflow\n");exit(2);}}
static int iszero(const Big*x){for(int i=0;i<N;i++)if(x->a[i])return 0;return 1;}
int main(void){
 FILE*f=fopen("bits.records","r"); if(!f)return 2; Big base,lo,hi,unit,bound,x; one(&base);for(int i=0;i<2500;i++)mulsmall(&base,255);zero(&lo);cp(&hi,&base);cp(&unit,&base);
