  {Big t;cp(&t,&unit);mulsmall(&t,off+sp);cp(&bound,&t);} 
  if(bit){if(cmp(&lo,&bound)<0)cp(&lo,&bound);off+=sp;rr-=sp;}else{if(cmp(&hi,&bound)>0)cp(&hi,&bound);rr=sp;}cnt[ix+bit]++;n++;if(cmp(&lo,&hi)>=0){fprintf(stderr,"empty %d\n",n);return 5;}}
 fclose(f);if(n<1000)return 6;cp(&x,&lo);unsigned char out[2500];for(int i=2499;i>=0;i--)out[i]=(unsigned char)(divsmall(&x,255)+1);if(!iszero(&x))return 7;f=fopen("data.comp","wb");if(!f)return 8;if(fwrite(out,1,2500,f)!=2500)return 9;fclose(f);fprintf(stderr,"records=%d bytes=2500\n",n);return 0;
}
