static int cmp(const Big*a,const Big*b){for(int i=N-1;i>=0;i--)if(a->a[i]!=b->a[i])return a->a[i]>b->a[i]?1:-1;return 0;}
static void ms(Big*x,uint32_t m){uint64_t c=0;for(int i=0;i<N;i++){uint64_t v=(uint64_t)x->a[i]*m+c;x->a[i]=v;c=v>>32;}if(c){fprintf(stderr,"overflow\n");exit(2);}}
static void as(Big*x,uint32_t v){uint64_t c=v;for(int i=0;i<N&&c;i++){c+=x->a[i];x->a[i]=c;c>>=32;}if(c){fprintf(stderr,"overflow\n");exit(2);}}
static uint32_t ds(Big*x,uint32_t d){uint64_t r=0;for(int i=N-1;i>=0;i--){uint64_t v=(r<<32)|x->a[i];x->a[i]=v/d;r=v%d;}return r;}
static void mul(Big*r,const Big*a,const Big*b){Big q;z(&q);for(int i=0;i<N;i++)if(b->a[i]){uint64_t c=0;for(int j=0;j+i<N;j++){uint64_t v=(uint64_t)a->a[j]*b->a[i]+q.a[i+j]+c;q.a[i+j]=v;c=v>>32;}if(c){fprintf(stderr,"overflow\n");exit(2);}}cp(r,&q);}
